--
-- Structure for view `v_category_menu_groups`
--
DROP TABLE IF EXISTS `v_category_menu_groups`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_category_menu_groups`  AS  select `cmg`.`id_category_menu_group` AS `id_category_menu_group`,`cmg`.`id_group` AS `id_group`,`mg`.`group_name` AS `group_name`,`cmg`.`id_category_menu` AS `id_category_menu` from (`category_menu_groups` `cmg` left join `master_group` `mg` on(`cmg`.`id_group` = `mg`.`id_group`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_cek_kegiatan_pptk`
--
DROP TABLE IF EXISTS `v_cek_kegiatan_pptk`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_cek_kegiatan_pptk`  AS  select `kegiatan`.`id_instansi` AS `id_instansi`,`kegiatan`.`kode_rekening_kegiatan` AS `kode_rekening_kegiatan`,`kegiatan`.`kode_tahap` AS `kode_tahap`,`kegiatan`.`nama_kegiatan` AS `nama_kegiatan` from `v_kegiatan_apbd` `kegiatan` where !(`kegiatan`.`kode_rekening_kegiatan` in (select `v_pptk_kegiatan`.`kode_rekening_kegiatan` from `v_pptk_kegiatan`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_desa`
--
DROP TABLE IF EXISTS `v_desa`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_desa`  AS  select left(`master_wilayah`.`kode`,5) AS `id_kab_kota`,left(`master_wilayah`.`kode`,8) AS `id_kec_kel`,left(`master_wilayah`.`kode`,13) AS `id_desa`,`master_wilayah`.`nama` AS `nama` from `master_wilayah` where left(`master_wilayah`.`kode`,2) = 13 and octet_length(`master_wilayah`.`kode`) = 13 ;

-- --------------------------------------------------------

--
-- Structure for view `v_informasi_user`
--
DROP TABLE IF EXISTS `v_informasi_user`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_informasi_user`  AS  select `users`.`id_user` AS `id_user`,`users`.`full_name` AS `full_name`,`users`.`id_sub_instansi` AS `id_sub_instansi`,(select `sub_instansi`.`nama_sub_instansi` from `sub_instansi` where `sub_instansi`.`id_sub_instansi` = `users`.`id_sub_instansi`) AS `nama_sub_instansi`,`kedudukan`.`nama_kedudukan` AS `nama_kedudukan`,`users`.`username` AS `username`,`users`.`email` AS `email`,`users`.`is_active` AS `is_active` from (`master_users` `users` left join `master_kedudukan` `kedudukan` on(`users`.`id_kedudukan` = `kedudukan`.`id_kedudukan`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_instansi`
--
DROP TABLE IF EXISTS `v_instansi`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_instansi`  AS  select `master_instansi`.`id_instansi` AS `id`,`master_instansi`.`nama_instansi` AS `text`,'TES' AS `title`,'300' AS `width`,'100' AS `height`,'https://docs.dhtmlx.com/diagram/samples/common/img/avatar-1.png' AS `img`,if(`master_instansi`.`position` = 'v','vertical',NULL) AS `dir` from `master_instansi` ;

-- --------------------------------------------------------

--
-- Structure for view `v_instansi_relation`
--
DROP TABLE IF EXISTS `v_instansi_relation`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_instansi_relation`  AS  select concat(`a`.`id_instansi`,'-',`b`.`id_instansi`) AS `id`,`a`.`id_instansi` AS `from`,`b`.`id_instansi` AS `to`,`b`.`nama_instansi` AS `nama_instansi`,'line' AS `type` from (`master_instansi` `b` left join `master_instansi` `a` on(`b`.`id_parent` = `a`.`id_instansi`)) having `b`.`id_instansi` <> 0 ;

-- --------------------------------------------------------

