-- Structure for view `v_kab_kota`
--
DROP TABLE IF EXISTS `v_kab_kota`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_kab_kota`  AS  select `master_wilayah`.`kode` AS `id_kab_kota`,`master_wilayah`.`nama` AS `nama` from `master_wilayah` where left(`master_wilayah`.`kode`,2) = 13 and octet_length(`master_wilayah`.`kode`) = 5 ;

