--
-- Structure for view `v_kegiatan_apbd`
--
DROP TABLE IF EXISTS `v_kegiatan_apbd`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_kegiatan_apbd`  AS  select `ka`.`id_instansi` AS `id_instansi`,`ka`.`kode_rekening_program` AS `kode_rekening_program`,concat(`ka`.`kode_opd`,`ka`.`kode_program`,`ka`.`kode_kegiatan`) AS `kode_rekening_kegiatan`,`ka`.`kode_tahap` AS `kode_tahap`,`ka`.`nama_kegiatan` AS `nama_kegiatan`,sum(`ka`.`belanja_pegawai`) AS `belanja_pegawai`,sum(`ka`.`belanja_barang_jasa`) AS `belanja_barang_jasa`,sum(`ka`.`belanja_modal`) AS `belanja_modal`,sum(`ka`.`belanja_pegawai` + `ka`.`belanja_barang_jasa` + `ka`.`belanja_modal`) AS `pagu`,`ka`.`akumulasi` AS `akumulasi` from `kegiatan_apbd` `ka` group by `ka`.`id_kegiatan`,`ka`.`kode_opd`,`ka`.`kode_tahap` ;

