--
-- Structure for view `v_kpa`
--
DROP TABLE IF EXISTS `v_kpa`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_kpa`  AS  select `u`.`id_user` AS `id_user`,`u`.`id_parent` AS `id_parent`,`u`.`id_instansi` AS `id_instansi`,`u`.`id_sub_instansi` AS `id_sub_instansi`,`u`.`id_kedudukan` AS `id_kedudukan`,`mi`.`nama_instansi` AS `nama_instansi`,`si`.`nama_sub_instansi` AS `nama_sub_instansi`,`u`.`full_name` AS `full_name`,(select count(0) from `sub_instansi` where `sub_instansi`.`id_kpa` = `u`.`id_sub_instansi`) AS `jml_pptk`,`u`.`foto` AS `foto` from (((`master_users` `u` left join `master_instansi` `mi` on(`u`.`id_instansi` = `mi`.`id_instansi`)) left join `sub_instansi` `si` on(`u`.`id_sub_instansi` = `si`.`id_sub_instansi`)) left join `master_kedudukan` `mk` on(`u`.`id_kedudukan` = `mk`.`id_kedudukan`)) where `u`.`id_kedudukan` = 2 ;

