DROP TABLE IF EXISTS `v_menu_groups`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_menu_groups`  AS  select `mnug`.`id_menu_group` AS `id_menu_group`,`m`.`id_category_menu` AS `id_category_menu`,`mnug`.`id_group` AS `id_group`,`mg`.`group_name` AS `group_name`,`mnug`.`id_menu` AS `id_menu`,`m`.`is_active` AS `is_active`,`m`.`order_number` AS `order_number`,`m`.`icon` AS `icon`,`m`.`menu_name` AS `menu_name`,`m`.`is_parent` AS `is_parent`,`m`.`link` AS `link` from ((`menu_groups` `mnug` left join `menu` `m` on(`mnug`.`id_menu` = `m`.`id_menu`)) left join `master_group` `mg` on(`mnug`.`id_group` = `mg`.`id_group`)) ;

